// 노트북 목록: 아래 노트북은 위 노트북 밑에 끝 이름만 들여 쓰고, 숫자는 누르면 보이는 기록 수(아래 노트북 포함)와 같게 센다.
function folderRowsHTML(){
 const set=new Set(folders),counts=new Map();
 for(const n of active()){let f=n.folder;for(;;){counts.set(f,(counts.get(f)||0)+1);const i=f.lastIndexOf('/');if(i<0)break;f=f.slice(0,i);}}
 const parentOf=f=>{const p=f.split('/');for(let i=p.length-1;i>0;i--){const a=p.slice(0,i).join('/');if(set.has(a))return a;}return '';};
 const cmp=(a,b)=>{if(a==='수집함'||b==='수집함')return a==='수집함'?-1:b==='수집함'?1:0;const x=a.split('/'),y=b.split('/');for(let i=0;i<Math.min(x.length,y.length);i++){const c=x[i].localeCompare(y[i],'ko');if(c)return c;}return x.length-y.length;};
 const list=[...folders].sort(cmp),many=list.length>24,kids=new Map();for(const f of list){const p=parentOf(f);if(p)kids.set(p,(kids.get(p)||0)+1);}
 const open=many?openFolders():new Set();if(many&&folder){open.add(folder);for(let p=parentOf(folder);p;p=parentOf(p))open.add(p);}
 const shown=f=>{if(!many)return true;for(let p=parentOf(f);p;p=parentOf(p))if(!open.has(p))return false;return true;};
 return list.filter(shown).map(f=>{const parent=parentOf(f);let depth=0;for(let p=parent;p;p=parentOf(p))depth++;const item=`<button class="nav-item ${depth?'sub-folder depth-'+Math.min(depth,3):''} ${folder===f?'active':''}" data-folder="${esc(f)}" title="${esc(f)}">${icon('folder')}<span>${esc(parent?f.slice(parent.length+1):f)}</span><small>${(counts.get(f)||0).toLocaleString()}</small></button>`;if(!many)return item;const has=kids.get(f);return `<div class="folder-row">${has?`<button type="button" class="fold ${open.has(f)?'open':''}" data-folder-toggle="${esc(f)}" aria-expanded="${open.has(f)}" aria-label="${esc(f)} 아래 노트북 ${open.has(f)?'접기':'펼치기'}">${icon('chevron')}</button>`:'<span class="fold-space"></span>'}${item}</div>`;}).join('');
}
function openFolders(){try{const v=JSON.parse(localStorage.getItem('pkos-folders-open')||'[]');return new Set(Array.isArray(v)?v.filter(x=>typeof x==='string'):[]);}catch{return new Set();}}
function toggleFolder(f){const open=openFolders();if(open.has(f))open.delete(f);else open.add(f);try{localStorage.setItem('pkos-folders-open',JSON.stringify([...open]));}catch{}const box=$('.folder-list');if(box)box.innerHTML=folderRowsHTML();}
function viewName(){return {all:'모든 기록',inbox:'수집함',review:'다시 보기',favorites:'즐겨찾기',trash:'휴지통',graph:'지식맵',overview:'서재 현황'}[view]||'모든 기록';}
// 자료 카드 제목의 앞머리(연도_묶음_)와 끝의 형식 표시(한글)·(PDF)는 목록·읽기·지도에서 덜어 낸다. 원래 제목은 편집 화면과 찾기에 그대로 있다.
function shortTitle(n){if(!n)return '';let v=shortTitles.get(n);if(v!==undefined)return v;const t=n.title||'';v=t||'제목 없는 기록';const m=/^((?:19|20)\d\d)_(.+)$/.exec(t);if(n.updatable===true&&m){let r=m[2];const seg=r.split('_')[0];if(r.includes('_')&&n.tags.includes(seg))r=r.slice(seg.length+1);r=r.replace(/\s*\((한글|PDF|PPT|워드|엑셀|문서|글|웹)\)$/,'').replace(/_+/g,' ').replace(/\s+/g,' ').trim();if(r)v=r;}else if(n.updatable===true&&(n.sourcePath||n.localPath)){const r=t.replace(/\s*\((한글|PDF|PPT|워드|엑셀|문서|글|웹)\)$/,'').trim();if(r)v=r;}shortTitles.set(n,v);return v;}
// 기본 순서의 날짜: 문서 카드는 파일 날짜, 블로그 글·영상은 올린 날, 직접 쓴 기록은 고친 날(카드 파일을 만든 시각이 아니라 자료의 날짜로 줄을 세운다).
const recDate=(n,k)=>k==='doc'?(n.created||n.updated):(k==='blog'||k==='video')&&/^\d{4}-\d{2}-\d{2}/.test(n.date||'')?n.date:n.updated;
// 노트북(아래 노트북 포함)마다 묶음 카드를 뺀 기록 수와 가장 최근 날짜. 묶음 카드는 목록에서 이 날짜로 줄을 선다.
function folderStats(){const idx=facets();if(folderStatsCache.key===facetKey)return folderStatsCache.map;const m=new Map();for(const n of active()){const k=idx.byId.get(n.id)?.kind;if(k==='hub')continue;const d=recDate(n,k);let f=n.folder;for(;;){const st=m.get(f)||{latest:'',count:0};st.count++;if(d>st.latest)st.latest=d;m.set(f,st);const i=f.lastIndexOf('/');if(i<0)break;f=f.slice(0,i);}}folderStatsCache={key:facetKey,map:m};return m;}
const hubFor=f=>{const idx=facets();return active().find(n=>n.folder===f&&idx.byId.get(n.id)?.kind==='hub');};
const dupKey=n=>{let k=dupKeys.get(n);if(k===undefined){k=sameDocKey(n);dupKeys.set(n,k);}return k;};
// 찾기 낱말이 있으면 관련도 순: 낱말 전체가 제목에 있으면 맨 앞, 제목 → 태그·노트북 → 본문에 나온 횟수, 같으면 최근 순.
function rankByQuery(list,query){const whole=normalize(query),terms=whole.split(/\s+/).filter(Boolean);if(!terms.length)return list;
 const score=n=>{const t=normalize(n.title),st=normalize(shortTitle(n)),f=normalize(n.folder),tags=n.tags.map(normalize),b=normalize(n.body),hub=rowIdx?.byId.get(n.id)?.kind==='hub';let v=0;if(st===whole||t===whole)v+=400;else if(st.startsWith(whole))v+=200;if(st.includes(whole))v+=hub?270:120;else if(t.includes(whole))v+=60;
  for(const x of terms){if(st.includes(x))v+=40;else if(t.includes(x))v+=20;if(tags.includes(x))v+=25;else if(tags.some(g=>g.includes(x)))v+=10;if(f.includes(x))v+=10;let c=0,i=b.indexOf(x);while(i>=0&&c<5){c++;i=b.indexOf(x,i+x.length);}v+=c*2;}return v;};
 return list.map((n,i)=>[n,score(n),i]).sort((a,b)=>b[1]-a[1]||a[2]-b[2]).map(x=>x[0]);}
function orderList(list,idx,{query='',inFolder=''}={}){if(!idx||sort!=='auto')return list;if(query.trim())return rankByQuery(list,query);
 const key=n=>{const k=idx.byId.get(n.id)?.kind;return k==='hub'?'':recDate(n,k);};const out=list.map((n,i)=>[n,key(n),i]).sort((a,b)=>b[1].localeCompare(a[1])||a[2]-b[2]).map(x=>x[0]);
 if(inFolder){const h=out.findIndex(n=>n.folder===inFolder&&idx.byId.get(n.id)?.kind==='hub');if(h>0)out.unshift(...out.splice(h,1));}return out;}
// 보기·노트북·태그를 처음 열 때 고르는 기록: 그 목록의 맨 앞(같은 순서 규칙)
const firstRecord=(o={})=>{const idx=o.view==='trash'?null:facets();return orderList(filterNotes(notes,{...o,sort:'updated'}),idx,{inFolder:o.folder||''})[0]?.id||'';};
// 기록 연결 창의 줄: 짧은 제목과 노트북·연도·종류. 고른 기록은 찾는 낱말이 바뀌어도 pickerSel에 남는다.
function linkPickerRows(query){const n=pickerNote;if(!n)return '';const idx=facets(),qy=String(query||'').trim(),pool=active().filter(o=>o.id!==n.id),small=pool.length<=200;let rows,head;
 if(qy){const found=rankByQuery(filterNotes(pool,{q:qy,sort:'updated'}),qy);rows=small?found:found.slice(0,60);head=found.length?`찾은 기록 ${found.length.toLocaleString()}개${found.length>rows.length?' 가운데 관련도가 높은 '+rows.length+'개':''}`:'찾은 기록이 없습니다';}
 else{const picked=pool.filter(o=>pickerSel.has(o.id)),seen=new Set(picked.map(o=>o.id)),sug=relations(n,notes).map(r=>r.note).filter(o=>o.id!==n.id&&!seen.has(o.id)).slice(0,8);for(const o of sug)seen.add(o.id);const rest=small?orderList(pool.filter(o=>!seen.has(o.id)),idx):[];rows=[...picked,...sug,...rest];head=sug.length?`${picked.length?'연결한 기록과 ':''}이 글과 낱말이 겹치는 기록${small?', 그 아래는 나머지 기록':''}`:small?'모든 기록':'찾을 낱말을 적으세요';}
 const sub=o=>{const r=idx.byId.get(o.id);return [o.folder.split('/').at(-1),r?.year?r.year+'년':'',r&&r.kind!=='note'?KINDS[r.kind]:''].filter(Boolean).join(' · ');};
 return `<p class="link-head">${esc(head)}</p>`+rows.map(o=>`<label class="link-row"><input type="checkbox" data-link-id="${esc(o.id)}" ${pickerSel.has(o.id)?'checked':''}><span><strong>${esc(shortTitle(o))}</strong><small>${esc(sub(o))}</small></span></label>`).join('');}
const kindSpans=(idx,list)=>{if(!idx)return '';const m=new Map();for(const n of list){const k=idx.byId.get(n.id)?.kind;if(k)m.set(k,(m.get(k)||0)+1);}return m.size>1?KIND_ORDER.filter(k=>m.get(k)).map(k=>'<span>'+esc(KINDS[k])+' '+m.get(k).toLocaleString()+'</span>').join(' · '):'';};
// 목록의 날짜: 블로그 글·영상은 올린 날, 문서 카드는 문서의 연도(모르면 파일 날짜), 직접 쓴 기록과 묶음은 고친 날.
let rowIdx=null;
function rowDate(n){const r=rowIdx?.byId.get(n.id),k=r?.kind;if((k==='blog'||k==='video')&&/^\d{4}-\d{2}-\d{2}/.test(n.date||''))return date(n.date.slice(0,10));if(k==='doc')return r.year?r.year+'년':date(n.created);if(k==='hub'){const st=folderStats().get(n.folder);return st?'기록 '+st.count.toLocaleString()+'개':'';}return date(n.updated);}
function thumbHTML(n){const pv=previewOf(n);if(!pv||pv.kind==='folder')return '';const src=pv.kind==='video'?`https://i.ytimg.com/vi/${pv.id}/mqdefault.jpg`:`https://drive.google.com/thumbnail?id=${pv.id}&sz=w480`;return `<img class="thumb" src="${esc(src)}" alt="" loading="lazy" decoding="async" draggable="false" referrerpolicy="no-referrer">`;}
function rowHTML(n){const r=rowIdx?.byId.get(n.id),k=r?.kind,card=n.updatable===true&&k&&k!=='note',right=card?(k==='doc'&&r.format?'문서 · '+r.format:KINDS[k]):(n.tags[0]||n.status);return `<button class="note-row ${selected===n.id?'selected':''}" data-note="${esc(n.id)}" ${selected===n.id?'aria-current="true"':''}><div class="note-eyebrow"><span class="eyebrow-name">${card?`<i class="kind-dot kind-${k}" aria-hidden="true"></i>`:''}${esc(n.folder.split('/').at(-1))}</span>${dupCount.get(n.id)?`<span class="dup-badge" title="같은 문서가 드라이브 ${dupCount.get(n.id)}곳에 있습니다. 한 줄로 묶었습니다.">같은 문서 ${dupCount.get(n.id)}곳</span>`:''}${n.favorite?icon('star'):''}</div>${layout==='cards'&&card?thumbHTML(n):''}<h2>${esc(shortTitle(n))}</h2><p>${esc((k==='video'&&Array.isArray(n.info)?n.info.filter(x=>Array.isArray(x)&&x[0]!=='올린 날').map(x=>x[1]).join(' · '):excerpt(n.body).slice(0,85))||(card?'본문 앞부분이 없습니다.':'아직 적은 내용이 없습니다.'))}</p><div class="note-meta"><time>${rowDate(n)}</time><span>${esc(right)}</span>${n.attachments.length?icon('file'):''}</div></button>`;}
function moreHTML(){return listShown<listRows.length?`<button type="button" class="list-more quiet" data-action="list-more">${(listRows.length-listShown).toLocaleString()}개 더 보기</button>`:'';}
function appendRows(){if(listShown>=listRows.length||!$('#note-list'))return;$('.list-more')?.remove();const next=listRows.slice(listShown,listShown+LIST_CHUNK);listShown+=next.length;$('#note-list').insertAdjacentHTML('beforeend',next.map(rowHTML).join('')+moreHTML());}
function renderList(){if(!$('#note-list'))return;listRows=filterNotes(notes,{view,folder,tag,q,fields:fields(),status,sort:sort==='auto'?'updated':sort});const idx=view==='trash'?null:facets();rowIdx=idx;if(idx&&!condEmpty(cond))listRows=listRows.filter(n=>matchCond(idx.byId.get(n.id),cond));
 listRows=orderList(listRows,idx,{query:q,inFolder:folder});
 // 드라이브 여러 폴더에 있는 같은 문서(제목·본문 앞부분이 같은 자료 카드)는 한 줄로 보인다.
 listMatched=listRows;const before=listRows.length;dupCount=new Map();if(idx){const first=new Map();listRows=listRows.filter(n=>{const k=dupKey(n);if(!k)return true;const f=first.get(k);if(f){dupCount.set(f.id,(dupCount.get(f.id)||1)+1);return false;}first.set(k,n);return true;});}const merged=before-listRows.length;
 $('#list-count').textContent=before.toLocaleString()+'개의 기록';if($('#list-merged'))$('#list-merged').textContent=merged?'같은 문서 '+merged.toLocaleString()+'개는 한 줄로 묶음':'';if($('#list-kinds'))$('#list-kinds').innerHTML=kindSpans(idx,listMatched);if(idx&&$('#cond-bar')){const was=$('#cond-bar .cond-panel');if(was)condOpen=was.open;}if(idx&&$('#cond-bar'))$('#cond-bar').innerHTML=!active().length?'':condBarHTML(cond,facetCounts(listMatched.map(n=>idx.byId.get(n.id)).filter(Boolean)),idx,{open:condOpen,active:!condEmpty(cond)||!!q.trim(),total:listMatched.length,years:[...new Set(idx.rows.map(r=>r.year).filter(Boolean))].sort((a,b)=>a-b)});const at=listRows.findIndex(n=>n.id===selected);listShown=Math.min(listRows.length,Math.max(LIST_CHUNK,at>=0&&at<600?at+40:0));$('#note-list').innerHTML=listRows.length?listRows.slice(0,listShown).map(rowHTML).join('')+moreHTML():listEmptyHTML();renderSummary(idx);}
// 빈 목록 안내는 서재가 비었는지, 검색 조건 때문인지, 보기·노트북이 비었는지에 따라 다르게 보인다.
function listEmptyHTML(){
 const box=(h,p,actions)=>`<div class="list-empty">${icon('search')}<h2>${h}</h2><p>${p}</p>${actions}</div>`;
 if(q||status)return box('찾은 기록이 없습니다','검색어, 검색 범위, 상태를 바꿔 보세요.',btn('clear-search','검색 조건 지우기'));
 if(!notes.some(n=>!n.deleted)&&view!=='trash')return box('아직 기록이 없습니다','새 기록을 쓰거나 파일을 가져오세요. 백업·카드 파일(.pkem)도 「파일 가져오기」로 넣을 수 있습니다.',btn('new','첫 기록 쓰기','plus')+btn('import','파일 가져오기','download'));
 if(folder)return box('이 노트북에 기록이 없습니다','새 기록을 쓰면 이 노트북에 담깁니다.',btn('new','새 기록','plus'));
 if(tag)return box('이 태그가 붙은 기록이 없습니다','다른 태그를 고르거나 「모든 기록」으로 돌아가세요.','');
 const [h,p]={inbox:['수집함이 비었습니다','상태가 ‘수집’인 기록이 여기에 모입니다.'],review:['오늘 다시 볼 기록이 없습니다','편집 화면의 「다시 볼 날짜」를 정하면 그날부터 여기에 나옵니다.'],favorites:['즐겨찾기한 기록이 없습니다','기록 위쪽의 별을 누르면 여기에 모입니다.'],trash:['휴지통이 비었습니다','휴지통으로 옮긴 기록은 여기에서 복원하거나 영구 삭제합니다.']}[view]||['기록이 없습니다','새 기록을 쓰거나 파일을 가져오세요.'];
 return box(h,p,view==='trash'?'':btn('new','새 기록','plus'));
}
// 조건·찾기로 좁힌 목록에서 기록을 고르지 않았으면 오른쪽에 찾은 기록의 분포를 보인다.
const summaryWanted=()=>view==='all'&&active().length>0&&(!condEmpty(cond)||!!q.trim()||!!folder||!!tag);
function renderSummary(idx){const doc=$('.document');if(!doc||draft||current())return;const want=!!idx&&summaryWanted(),has=!!$('#cond-summary');if(want!==has)doc.innerHTML=emptyHTML();if(want)$('#cond-summary').innerHTML=condSummaryHTML(listMatched.map(n=>idx.byId.get(n.id)).filter(Boolean),idx,cond,{label:condLabel()});}
function emptyHTML(){if(summaryWanted())return '<div id="cond-summary"></div>';if(active().length)return `<div class="welcome pick-note"><span class="welcome-icon">${icon('book')}</span><p class="eyebrow">기록 ${active().length.toLocaleString()}개</p><h1>읽을 기록을 고르세요</h1><p>목록에서 기록을 누르면 여기에서 읽습니다.<br>새 생각은 「새 기록」에 적습니다.</p><div>${btn('new','새 기록','plus','primary')}${btn('overview','서재 현황','grid')}${btn('layout','카드로 보기','grid')}</div></div>`;return `<div class="welcome"><span class="welcome-icon">${icon('book')}</span><p class="eyebrow">생각을 모으고, 다시 꺼내 쓰는 곳</p><h1>나의지식서재</h1><p>떠오른 생각 한 줄부터 시작하세요.<br>기록은 노트북으로 정리하고 서로 연결할 수 있습니다.</p><div>${btn('new','첫 기록 쓰기','plus','primary')}${btn('import','파일 가져오기','download')}</div>${!demo?'<a class="text-link" href="?demo=1">가상 자료 48개로 먼저 살펴보기</a>':''}<small>로그인 없이 이 기기에 저장합니다.<br>다른 기기로 옮기려면 설정에서 백업을 내보내세요.</small></div>`;}
function cardStamp(n){const r=facets().byId.get(n.id),k=r?.kind;if(!k||k==='note')return '';if(k==='hub'){const st=folderStats().get(n.folder);return KINDS[k]+(st?' · 기록 '+st.count.toLocaleString()+'개':'');}const d=(k==='blog'||k==='video')&&/^\d{4}-\d{2}-\d{2}/.test(n.date||'')?date(n.date.slice(0,10)):k==='doc'?(r.year?r.year+'년':date(n.created)):date(n.updated);return KINDS[k]+' · '+d;}
function docTop(n,editing=false){return `<div class="document-toolbar">${btn('back','목록','back','quiet back-button')}<div class="save-status"><span class="document-state" id="save-state">${editing?'편집 중':n.deleted?'휴지통의 기록':(n.updatable===true&&cardStamp(n))||date(n.updated)+' 수정'}</span><button type="button" class="document-state mirror-indicator" data-action="folder-mirror" data-mirror-indicator hidden><span data-mirror-status>로컬 폴더 저장 대기</span></button></div><div class="doc-actions">${!n.deleted?btn('writing-focus','집중','book','quiet focus-toggle','aria-pressed="false" title="집중 모드"'):''}${/^https:\/\//.test(n.openUrl||'')?`<a class="open-original" href="${esc(n.openUrl)}" target="_blank" rel="noopener noreferrer">${icon('link')}<span>${n.openUrl.includes('/folders/')?'폴더 열기':'원본 열기'}</span></a>`:''}${!n.deleted&&!editing?btn('favorite',n.favorite?'즐겨찾기 해제':'즐겨찾기','star','icon-button '+(n.favorite?'is-favorite':''),`aria-pressed="${!!n.favorite}"`):''}${editing?btn('save','저장','check','primary small'):n.deleted?btn('restore','복원','back','primary small'):btn('edit','편집','edit','quiet')}${btn('note-menu','더 보기','more','icon-button')}</div></div>`;}
function readerHTML(n){const card=n.updatable===true,information=infoHTML(n);return `${docTop(n)}<article class="page"><div class="page-eyebrow">${icon('folder')} ${esc(n.folder.split('/').join(' › '))}${card?'':`<span class="status-pill">${esc(n.status)}</span>`}</div><h1 class="page-title"${shortTitle(n)!==(n.title||'제목 없는 기록')?` title="${esc(n.title)}"`:''}>${esc(shortTitle(n))}</h1>${chipRowHTML(n)}${information?'<details class="reader-info"><summary>자료 정보 · 원본 위치</summary>'+information+'</details>':''}${previewHTML(n)}${n.mdPath?'<p class="excerpt-label">본문 앞부분</p>':''}<div id="markdown" class="prose${card&&facets().byId.get(n.id)?.kind==='doc'?' excerpt-text':''}"></div>${n.database?'<div id="note-database"></div>':''}${n.mdPath?'<p class="excerpt-foot">전체 글은 위 「마크다운 사본」에 있습니다. 이름·전화번호 같은 개인정보는 가려 두었습니다.</p>':''}<div id="document-pages"></div><div id="attachments" class="attachments"></div>${facets().byId.get(n.id)?.kind==='hub'?hubHTML(n):relatedHTML(n)+sameTimeHTML(n)}</article>`;}
// 속성 줄 하나: 출처·연도·형식·주제(누르면 조건) 뒤에 태그. 카드는 이 줄·노트북과 겹치는 태그(연도, 형식, 출처, 영역)를 뺀다.
const CARD_PLAIN_TAGS=new Set(['한글','PDF','PPT','워드','문서','글','웹','엑셀','블로그','유튜브','묶음','영역']);
function chipRowHTML(n){const area=n.folder.split('/')[0],tags=n.updatable===true?n.tags.filter(t=>!/^\d{4}$/.test(t)&&!CARD_PLAIN_TAGS.has(t)&&t!==area):n.tags;return `<div class="page-tags">${facetLine(n)}${tags.map(t=>`<button data-tag="${esc(t)}" class="tag">#${esc(t)}</button>`).join('')}${n.reviewDate?'<span class="review-date">다시 볼 날 '+esc(n.reviewDate)+'</span>':''}</div>`;}
// 사본·원래 자리: 구글 드라이브 링크(https), 탐색기(pkos-open: 링크, 이 PC에 'PKOS 탐색기 연결' 설치 필요), 경로 복사.
// 경로는 내 드라이브 기준 상대 경로만 받는다.
const placeRel=rel=>typeof rel==='string'&&rel.length>0&&!/:|^[\\/]|(^|[\\/])\.{1,2}([\\/]|$)/.test(rel);
function placeRow(label,url,rel,folder){const web=/^https:\/\//.test(url||''),local=placeRel(rel);if(!web&&!local)return '';
 return `<div class="place-row"><span class="place-label">${label}</span>${web?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${icon('link')}<span>${webLabel(url)}</span></a>`:''}${local?`<a href="${esc('pkos-open:?mode='+(folder?'folder':'select')+'&path='+encodeURIComponent(rel))}" title="이 PC에 PKOS 탐색기 연결이 설치되어 있으면 탐색기에서 엽니다">${icon('folder')}<span>탐색기</span></a><button type="button" class="quiet" data-action="copy-path" data-path="${esc(driveRoot()+rel.replace(/\//g,'\\'))}">경로 복사</button>`:''}</div>`;}
const webLabel=u=>/youtu\.?be/.test(u)?'유튜브':/blog\.naver\.com/.test(u)?'블로그':/(drive|docs)\.google\.com/.test(u)?'구글 드라이브':'웹 페이지';
// 자료 정보 상자: 카드의 info(묶음·형식·폴더·원래 이름…)와 열 수 있는 자리(사본, 원래 자리, 마크다운 사본).
// 미리보기 주소: 구글 드라이브 파일(/preview), 드라이브 폴더(embeddedfolderview), 유튜브(youtube-nocookie). 사본을 먼저 본다.
function previewOf(n){for(const u of [n.openUrl,n.sourceUrl]){const s=String(u||'');let m=/^https:\/\/drive\.google\.com\/file\/d\/([\w-]{10,})/.exec(s);if(m)return {kind:'file',id:m[1],src:`https://drive.google.com/file/d/${m[1]}/preview`};m=/^https:\/\/drive\.google\.com\/drive\/folders\/([\w-]{10,})/.exec(s);if(m)return {kind:'folder',id:m[1],src:`https://drive.google.com/embeddedfolderview?id=${m[1]}#grid`};m=/^https:\/\/(?:youtu\.be\/|(?:www\.)?youtube\.com\/watch\?v=)([\w-]{6,})/.exec(s);if(m)return {kind:'video',id:m[1],src:`https://www.youtube-nocookie.com/embed/${m[1]}`};}return null;}
const previewOn=()=>{try{return localStorage.getItem('pkos-preview')==='on';}catch{return false;}};
function previewHTML(n){const pv=previewOf(n);if(!pv)return '';const on=previewOn(),label=pv.kind==='video'?'영상':pv.kind==='folder'?'폴더 미리보기':'드라이브 미리보기';return `<div class="preview-bar"><button type="button" class="quiet preview-toggle" data-action="preview-toggle" aria-expanded="${on}">${icon(on?'close':'grid')}<span>${on?label+' 닫기':label}</span></button></div>${on?`<div class="drive-preview kind-${pv.kind}"><iframe src="${esc(pv.src)}" title="${esc(n.title)} ${label}" loading="lazy" sandbox="allow-scripts allow-same-origin${pv.kind==='video'?' allow-presentation':''}" allow="${pv.kind==='video'?'fullscreen; picture-in-picture':''}" ${pv.kind==='video'?'allowfullscreen':''} referrerpolicy="strict-origin-when-cross-origin"></iframe><p class="hint">${pv.kind==='video'?'보기 전용입니다. 이 칸에서는 새 창 열기가 막혀 있습니다.':'보기 전용입니다. 이 칸에서는 내려받기·인쇄·새 창 열기가 막혀 있고, 그 파일을 볼 권한이 있는 구글 계정으로 로그인한 브라우저에서만 보입니다. 보이지 않으면 「원본 열기」로 새 탭에서 엽니다.'}</p></div>`:''}`;}
function infoHTML(n){const rows=(Array.isArray(n.info)?n.info:[]).filter(r=>Array.isArray(r)&&r.length>1&&String(r[1]).trim()),hub=n.links?.length?active().find(x=>x.id===n.links[0]):null,places=placesRows(n),fam=docFamily(n,notes),idx=facets();
 const famRows=[['같은 문서',fam.copies.map(c=>[c,copyPlace(c)])],['같은 이름',fam.formats.map(c=>[c,[idx.byId.get(c.id)?.format,infoValue(c,'파일 날짜')].filter(Boolean).join(' ')||shortTitle(c)])]].filter(([,l])=>l.length);
 if(!rows.length&&!places&&!famRows.length)return '';return `<div class="file-places">${rows.length||famRows.length?`<dl class="info-rows">${rows.map(([k,v])=>`<div class="${String(v).length>14||['묶음','폴더','원래 이름','담긴 것'].includes(k)?'wide':''}"><dt>${esc(k)}</dt><dd>${(k==='묶음'||k==='영역')&&hub&&hub.title===String(v)?`<button type="button" class="link-button" data-note="${esc(hub.id)}">${esc(v)}</button>`:esc(v)}</dd></div>`).join('')}${famRows.map(([k,l])=>`<div class="wide family"><dt>${k}</dt><dd>${l.map(([c,t])=>`<button type="button" class="link-button" data-note="${esc(c.id)}" title="${esc(c.title)}">${esc(t)}</button>`).join('<span class="sep"> · </span>')}</dd></div>`).join('')}</dl>`:''}${places}</div>`;}
const infoValue=(c,k)=>String((Array.isArray(c.info)?c.info:[]).find(r=>Array.isArray(r)&&r[0]===k)?.[1]||'');
// 같은 문서가 놓인 다른 자리: 카드의 「폴더」 끝 두 단계(없으면 노트북 이름)
const copyPlace=c=>{const f=(Array.isArray(c.info)?c.info:[]).find(r=>Array.isArray(r)&&r[0]==='폴더')?.[1];return f?String(f).split(' › ').slice(-2).join(' › '):c.folder.split('/').at(-1);};
function placesRows(n){const kd=facets().byId.get(n.id)?.kind;let rows;if(kd==='blog'||kd==='video')rows=placeRow('원문',n.sourceUrl||n.openUrl,'',false)+placeRow('마크다운 사본','',n.localPath,false);else{const folder=(n.openUrl||'').includes('/folders/');rows=placeRow(folder?'폴더':'사본',n.openUrl,n.localPath,folder)+placeRow('원래 자리',n.sourceUrl,n.sourcePath,false)+placeRow('마크다운 사본','',n.mdPath,false);}if(!rows)return '';return `<div class="place-rows">${rows}</div>${[n.localPath,n.sourcePath,n.mdPath].some(placeRel)?'<button type="button" class="link-button place-help" data-action="prereq">탐색기·경로 복사 준비</button>':''}`;}
function relatedHTML(n){const rows=relations(n,notes).slice(0,5);return `<section class="related"><header><div><span class="eyebrow">생각 이어가기</span><h2>함께 읽을 기록</h2></div>${btn('link-picker','기록 연결','plus','quiet small')}</header>${rows.length?rows.map(r=>`<button class="related-row" data-note="${esc(r.note.id)}">${icon('all')}<span><strong>${esc(shortTitle(r.note))}</strong><small>${esc(r.why)}</small></span>${icon('link')}</button>`).join(''):'<p class="muted">참고한 기록을 연결하면 이곳에서 다시 찾을 수 있습니다.</p>'}</section>`;}
// 묶음·영역 카드: 안에 든 기록 수, 연도·형식·주제 분포, 아래 묶음(영역 카드), 최근 기록 5개, 목록으로 보기
function hubHTML(n){const idx=facets(),f=n.folder,members=active().filter(x=>x.id!==n.id&&(x.folder===f||x.folder.startsWith(f+'/'))&&idx.byId.get(x.id)?.kind!=='hub');if(!members.length)return relatedHTML(n);
 const tally=(get)=>{const m=new Map();for(const x of members)for(const k of [].concat(get(idx.byId.get(x.id))||[]))if(k)m.set(k,(m.get(k)||0)+1);return [...m.entries()];};
 const years=tally(r=>r?.year).sort((a,b)=>a[0]-b[0]),formats=tally(r=>r?.format).sort((a,b)=>b[1]-a[1]).slice(0,4),themes=tally(r=>r?.themes).sort((a,b)=>b[1]-a[1]).slice(0,4);
 const st=folderStats(),kids=active().filter(x=>x.id!==n.id&&x.folder.startsWith(f+'/')&&idx.byId.get(x.id)?.kind==='hub').sort((a,b)=>(st.get(b.folder)?.count||0)-(st.get(a.folder)?.count||0));
 const recent=members.slice().sort((a,b)=>b.updated.localeCompare(a.updated)).filter((x,i,arr)=>{const k=dupKey(x);return !k||arr.findIndex(y=>dupKey(y)===k)===i;}).slice(0,5);
 const line=(label,list,fmt)=>list.length?`<p class="hub-line"><span>${label}</span>${list.map(fmt).join(' · ')}</p>`:'';
 return `<section class="related hub-members"><header><div><span class="eyebrow">${kids.length?'영역 안 묶음과 기록':'묶음 안 기록'}</span><h2>기록 ${members.length.toLocaleString()}개</h2></div><button type="button" class="quiet small" data-folder="${esc(f)}">목록으로 보기</button></header>${kids.length?`<div class="hub-kids">${kids.map(h=>`<button type="button" class="hub-kid" data-note="${esc(h.id)}"><strong>${esc(h.title)}</strong><small>${(st.get(h.folder)?.count||0).toLocaleString()}개</small></button>`).join('')}</div>`:''}${line('연도',years.length>8?[[years[0][0]+'~'+years.at(-1)[0],members.length]]:years,([y,c])=>`${y}년 ${c.toLocaleString()}`)}${line('형식',formats,([k,c])=>`${esc(k)} ${c.toLocaleString()}`)}${line('주제',themes,([t,c])=>`${esc(idx.label[t]||t)} ${c.toLocaleString()}`)}<p class="hub-sub">최근 기록</p>${recent.map(x=>`<button class="related-row" data-note="${esc(x.id)}">${icon('all')}<span><strong>${esc(shortTitle(x))}</strong><small>${esc([x.folder.split('/').at(-1),idx.byId.get(x.id)?.year?idx.byId.get(x.id).year+'년':'',idx.byId.get(x.id)?.format||''].filter(Boolean).join(' · '))}</small></span>${icon('link')}</button>`).join('')}</section>`;}
function previewKind(a){return /\.pdf$/i.test(a?.name||'')||a?.type==='application/pdf'?'pdf':/\.pptx$/i.test(a?.name||'')?'pptx':/\.ppt$/i.test(a?.name||'')?'ppt':'';}
function attachmentPreviewButton(a){const kind=previewKind(a);return kind?btn('preview-pdf',kind==='pdf'?'PDF 미리보기':'슬라이드 미리보기','','quiet small','data-asset="'+esc(a.id)+'"'):'';}
function renderBody(n){let md=n.body.replace(/\[\[([^\]|]+)(?:\|([^\]]*))?\]\]/g,(_,name,label)=>{const target=active().find(n=>n.title.trim().toLowerCase()===name.trim().toLowerCase());return target?`[${label||name}](#note=${encodeURIComponent(target.id)})`:`\`${label||name}\` (연결할 기록 없음)`;});const html=DOMPurify.sanitize(marked.parse(md,{breaks:true}),{FORBID_TAGS:['style','iframe','object','embed','form','button','select','textarea'],FORBID_ATTR:['style'],ALLOW_DATA_ATTR:false});const inert=document.createElement('template');inert.innerHTML=html;inert.content.querySelectorAll('img').forEach(img=>img.replaceWith(Object.assign(document.createElement('span'),{className:'image-placeholder',textContent:'외부 이미지: '+(img.alt||img.getAttribute('src')||'')+' (첨부 파일로 보관하세요)'})));$('#markdown').innerHTML=inert.innerHTML;$$('#markdown input').forEach(input=>{if(input.type==='checkbox'){input.disabled=true;input.removeAttribute('name');input.removeAttribute('id');}else input.remove();});$$('#markdown a').forEach(a=>{if((a.getAttribute('href')||'').startsWith('#note=')){try{a.dataset.note=decodeURIComponent(a.hash.slice(6));}catch{a.removeAttribute('href');}}else{a.target='_blank';a.rel='noopener noreferrer';}});$$('#markdown img').forEach(img=>{const src=img.getAttribute('src')||'';img.replaceWith(Object.assign(document.createElement('span'),{className:'image-placeholder',textContent:'외부 이미지: '+(img.alt||src)+' (첨부 파일로 보관하세요)'}));});$('#attachments').innerHTML=(n.folderSource?'<p class="hint">가져온 위치: '+esc(n.folderSource.folder||'연결 폴더')+' / '+esc(n.folderSource.path)+'</p>':'')+n.attachments.filter(id=>!pageAssetIds(n).has(id)).map(id=>{const a=assets.find(a=>a.id===id);if(!a)return '<p class="error">첨부를 찾을 수 없습니다.</p>';const url=URL.createObjectURL(a.blob);urls.push(url);return `<div class="attachment-card">${a.type.startsWith('image/')?`<img src="${url}" alt="${esc(a.name)}" loading="lazy">`:a.type.startsWith('audio/')?`<audio controls src="${url}" aria-label="${esc(a.name)}"></audio>`:a.type.startsWith('video/')?`<video controls src="${url}" aria-label="${esc(a.name)}"></video>`:''}<a href="${url}" download="${esc(a.name)}">${icon('file')}<span>${esc(a.name)}<small>${formatBytes(a.blob.size)} · 원본 다운로드</small></span>${icon('download')}</a>${convertible(a.name)?btn('convert-document','본문·이미지 추출','','quiet small','data-asset="'+a.id+'"'):''}${attachmentPreviewButton(a)}${pageConvertButton(a)}${processingButtons(a)}</div>`;}).join('');enhanceBlockContent($('#markdown'),{notes,assets,noteId:n.id,trail:[n.id],assetURL:a=>{const url=URL.createObjectURL(a.blob);urls.push(url);return url;},mountDatabase:mountNoteDatabase,previewAsset:id=>{const button=document.createElement('button');button.dataset.action='preview-pdf';button.dataset.asset=id;document.body.append(button);button.click();button.remove();}});if(n.database)mountNoteDatabase($('#note-database'),n);}
function mountNoteDatabase(host,n,viewId){return mountDatabase(host,{value:n.database,noteId:n.id,viewId,getNotes:()=>notes,getAssets:()=>assets.filter(a=>notes.find(x=>x.id===n.id)?.attachments.includes(a.id)),addFiles:files=>addDatabaseFiles(n.id,files),toast,download,save:(value,expected)=>saveDatabaseContent(n.id,value,expected),saveOther:saveDatabaseContent});}
async function saveDatabaseContent(id,value,expected){const fresh=await db.get('notes',id);if(!fresh||fresh.deleted||fresh.database!==expected)throw Error('다른 창이나 보기에서 데이터베이스를 바꿨습니다. 현재 구조·내용 사본을 내려받아 보존한 뒤 다시 열어 주세요.');const saved=await db.save({...fresh,database:value},fresh.revision);notes=notes.map(x=>x.id===saved.id?saved:x);channel?.postMessage({id:saved.id});return saved;}
const formatBytes=b=>b>=1048576?(b/1048576).toFixed(1)+' MB':Math.max(1,Math.round(b/1024))+' KB';
function editorHTML(){const n=draft;return `<div class="editor-header">${docTop(n,true)}<div class="page editor-heading"><label class="sr-only" for="edit-title">제목</label><input id="edit-title" class="title-input" placeholder="제목 없는 기록" value="${esc(n.title)}" maxlength="500"><details class="properties"><summary>노트북 · 태그 · 다시 볼 날짜</summary><div class="property-grid"><label>노트북<select id="edit-folder">${[...new Set([...folders,n.folder])].map(f=>`<option ${f===n.folder?'selected':''}>${esc(f)}</option>`).join('')}</select></label><label>상태<select id="edit-status">${['수집','정리 중','활용','보관'].map(v=>`<option ${n.status===v?'selected':''}>${v}</option>`).join('')}</select></label><label>태그<input id="edit-tags" value="${esc(n.tags.join(', '))}" placeholder="쉼표로 구분"></label><label>다시 볼 날짜<input id="edit-review" type="date" value="${esc(n.reviewDate)}"></label></div><div class="tag-suggest" id="tag-suggest"></div></details><div class="format-bar" aria-label="글 서식"><div class="editor-tools-main">${btn('bold','굵게','','format','title="굵게 (Ctrl B)"')}${btn('heading','소제목','','format')}${btn('attach','첨부','plus','format')}<button type="button" class="format" data-editor-tool="record">녹음</button><button type="button" class="format" data-editor-tool="dictate">받아쓰기</button>${btn('editor-tools',editorToolsOpen?'도구 접기':'도구 더 보기','more','format tools-toggle',`aria-expanded="${editorToolsOpen}" aria-controls="editor-extra-tools"`)}</div><div id="editor-extra-tools" class="editor-tools-extra" ${editorToolsOpen?'':'hidden'}>${btn('italic','기울임','','format')}${btn('bullet','목록','','format')}${btn('quote','인용','','format')}<button type="button" class="format" data-editor-tool="commands" title="본문의 새 줄에서 /를 입력해도 열립니다">/ 넣기</button><button type="button" class="format" data-editor-tool="camera">사진 촬영</button>${btn('link-picker','기록 연결','link','format')}${btn('preview','저장하고 읽기','book','format','title="저장하고 읽기 (Ctrl E)"')}</div></div></div></div><div class="page editor-page"><label for="edit-body" class="sr-only">본문</label><textarea id="edit-body" maxlength="2000000" placeholder="여기에 생각을 적으세요. 새 줄에 /를 입력하면 제목·표·할 일·첨부 등을 고를 수 있습니다." spellcheck="false">${esc(n.body)}</textarea><div class="editor-footer"><span id="word-count">${n.body.length.toLocaleString()}자</span><span>자동 저장 · Ctrl S</span></div><div id="document-pages"></div><div class="editing-files">${n.attachments.filter(id=>!pageAssetIds(n).has(id)).map(id=>{const a=assets.find(a=>a.id===id);return `<div>${icon('file')}<span>${esc(a?.name||'첨부')}</span>${attachmentPreviewButton(a)}${pageConvertButton(a)}${processingButtons(a)}${btn('detach','첨부 해제','close','icon-button',`data-asset="${id}"`)}</div>`;}).join('')}</div><section class="save-recovery" role="status" ${saveError?'':'hidden'}><strong>현재 글을 안전하게 보관하세요</strong><p>다른 창의 기록은 덮어쓰지 않습니다. 새 사본으로 저장하거나 글을 파일로 내려받을 수 있습니다.</p>${btn('save-copy','현재 글을 새 사본으로 저장','all','primary small')}${btn('export-note','글 파일로 보관','download')}</section></div>`;}
function wireEditor(){for(const id of ['edit-title','edit-body','edit-folder','edit-status','edit-tags','edit-review'])$('#'+id).addEventListener('input',()=>{draft.title=$('#edit-title').value;draft.body=$('#edit-body').value;draft.folder=$('#edit-folder').value;draft.status=$('#edit-status').value;draft.tags=tagsOf($('#edit-tags').value);draft.reviewDate=$('#edit-review').value;dirty=true;$('#word-count').textContent=draft.body.length.toLocaleString()+'자';setSaveState('저장 대기');clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveDraft(false),700);});}
function setSaveState(text,error=false){const el=$('#save-state');if(el){el.textContent=text;el.classList.toggle('error',error);}const recovery=$('.save-recovery');if(recovery)recovery.hidden=!error;}
function renderDocumentPagesUI(){
 const host=$('#document-pages'),note=draft||current();if(!host||!note)return;
 host.innerHTML=documentPagesHTML(note,assets,asset=>{const url=URL.createObjectURL(asset.blob);urls.push(url);return url;},!!draft);
 host.querySelectorAll('[data-page-comment]').forEach(input=>input.addEventListener('input',()=>{
  const page=pagesOf(draft).find(p=>p.id===input.dataset.pageComment);if(!page)return;
  page.comment=input.value;dirty=true;setSaveState('저장 대기');clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveDraft(false),700);
 }));
}
async function changeDocumentPage(id,deleted){
 const owner=draft||current(),page=pagesOf(owner).find(p=>p.id===id);if(!page||page.deleted===deleted)return;
 if(deleted&&!await ask('페이지 삭제',page.number+'페이지와 이 페이지의 의견을 지웁니다. 연결한 로컬 폴더의 해당 이미지 파일도 삭제합니다. 원본 PDF·PPT와 다른 페이지는 유지됩니다.',{value:null,confirm:'페이지 삭제',danger:true}))return;
 if(draft&&!await saveDraft(false))return;
 const note=draft||current();if(note?.id!==owner.id)return;
 const image=assets.find(a=>a.id===page.assetId);if(!deleted&&!image)throw Error('복원할 이미지가 없습니다. 원본을 다시 첨부해 주세요.');
 const next={...note,documentPages:pagesOf(note).map(p=>p.id===id?{...p,deleted}:p),attachments:deleted?note.attachments.filter(a=>a!==page.assetId):[...new Set([...note.attachments,page.assetId])]};
 if(draft){draft=next;dirty=true;if(!await saveDraft(false))return;}
 else{const saved=await db.save(next,note.revision);notes=notes.map(n=>n.id===saved.id?saved:n);channel?.postMessage({id:saved.id});await folderMirror?.sync();}
 render();toast(deleted?'페이지를 삭제했습니다.':'페이지와 의견을 복원했습니다.');
}
async function saveDraft(exit=false){clearTimeout(saveTimer);if(saving){await saving;if(dirty)return saveDraft(exit);if(exit&&draft&&!saveError){draft=null;render();}return !saveError;}if(!draft)return true;if(!dirty){await folderMirror?.sync();if(dirty||saving)return saveDraft(exit);if(exit){draft=null;render();}return true;}const snapshot=structuredClone(draft);setSaveState('저장 중');saving=(async()=>{try{const saved=await db.save(snapshot,snapshot.revision);const idx=notes.findIndex(n=>n.id===saved.id);if(idx<0)notes.unshift(saved);else notes[idx]=saved;if(draft?.id===saved.id){draft.revision=saved.revision;draft.updated=saved.updated;dirty=JSON.stringify({...draft,revision:snapshot.revision,updated:snapshot.updated})!==JSON.stringify(snapshot);}saveError='';setSaveState('저장됨');channel?.postMessage({id:saved.id});renderList();await folderMirror?.sync();return true;}catch(e){saveError=e.message;setSaveState('저장 실패 · 글은 편집창에 남아 있습니다',true);toast(e.message);return false;}})();const ok=await saving;saving=null;if(dirty&&ok)return saveDraft(exit);if(exit&&ok){draft=null;render();}return ok;}
async function navigate(fn){if(!await flushDatabases())return;if(draft&&!(await saveDraft(false)))return;draft=null;dirty=false;fn();hashPush=true;document.body.classList.remove('nav-open');render();}
async function openNote(id){await navigate(()=>{selected=id;if(view==='graph')view='all';if(layout==='cards'&&innerWidth>700)layout='list';});$('.document')?.scrollTo(0,0);}
async function newNote(template='blank'){if(!await flushDatabases())return;if(draft&&!(await saveDraft(false)))return;view='all';selected='';const templates={blank:'',meeting:'## 오늘 나눈 이야기\n\n\n## 결정한 내용\n\n- \n\n## 다음 행동\n\n- [ ] ',reading:'## 출처\n\n\n## 기억할 문장\n\n> \n\n## 내 생각\n\n\n## 어디에 활용할까\n\n',lesson:'## 수업에서 확인할 것\n\n\n## 관찰한 장면\n\n\n## 다음 수업에 바꿀 것\n\n- [ ] '};draft=makeNote({folder:folder||'수집함',body:templates[template]||''});selected=draft.id;dirty=true;saveError='';document.body.classList.remove('nav-open');render();$('#edit-title').focus();}
function dialog(title,body,actions=''){const d=$('#dialog');if(d.open)d.close();d.classList.remove('document-preview-dialog');d.innerHTML=`<header><h2 id="dialog-title">${esc(title)}</h2>${btn('dialog-close','닫기','close','icon-button')}</header><div class="dialog-body">${body}</div>${actions?'<footer>'+actions+'</footer>':''}`;d.showModal();return d;}
function ask(title,text,{value='',label='이름',confirm='확인',danger=false}={}){return new Promise(resolve=>{const d=dialog(title,`<p>${esc(text)}</p>${value!==null?`<label>${esc(label)}<input id="ask-value" value="${esc(value)}" maxlength="200"></label>`:''}`,btn('ask-cancel','취소')+btn('ask-ok',confirm,'',danger?'danger':'primary'));let done=false;const finish=v=>{if(done)return;done=true;d.close();d.removeEventListener('click',click);d.removeEventListener('cancel',cancel);resolve(v);};const click=e=>{const a=e.target.closest('[data-action]')?.dataset.action;if(a==='ask-ok')finish(value===null?true:$('#ask-value').value.trim());if(['ask-cancel','dialog-close'].includes(a))finish(null);};const cancel=()=>finish(null);d.addEventListener('click',click);d.addEventListener('cancel',cancel,{once:true});$('#ask-value')?.focus();});}
function cardSyncRows(){const c=cardSync?.status();return c?`<div class="setting-row card-sync-row">${icon('inbox')}<span>자료 카드 파일 <strong>${esc(c.name)}</strong><small>${c.syncedAt?'마지막 반영 '+esc(new Date(c.syncedAt).toLocaleString('ko-KR')):'아직 반영 전'} · 앱을 켤 때와 창으로 돌아올 때 자동 반영</small></span></div>${btn('card-sync-now','카드 파일 지금 다시 반영','back','setting-row')}${btn('card-sync-off','카드 파일 연결 끊기','trash','setting-row')}`:btn('card-sync-connect','자료 카드 파일 연결 · 켤 때 자동 반영','inbox','setting-row');}
// 왼쪽 태그 목록: 주제 태그(많은 순)와, 접어 둔 연도·형식·출처·영역 태그. 태그를 고른 동안은 펼쳐 둔다.
function fillTagSuggest(){const box=$('#tag-suggest');if(!box||!draft)return;const have=new Set(tagsOf($('#edit-tags')?.value||'')),areas=new Set(active().map(n=>n.folder.split('/')[0])),ok=t=>!have.has(t)&&!metaTag(t)&&!areas.has(t),score=new Map();
 if((draft.title+' '+draft.body).trim().length>=10)for(const r of relations(draft,notes).slice(0,12))for(const t of r.note.tags)if(ok(t))score.set(t,(score.get(t)||0)+r.score);
 let list=[...score.entries()].sort((a,b)=>b[1]-a[1]).map(([t])=>t).slice(0,6),label='이 글과 비슷한 기록의 태그';if(!list.length){list=tagCounts().map(([t])=>t).filter(ok).slice(0,6);label='자주 쓰는 태그';}
 box.innerHTML=list.length?`<span>${label}</span>${list.map(t=>`<button type="button" class="tag" data-add-tag="${esc(t)}">+ ${esc(t)}</button>`).join('')}`:'';}
function sideTagsHTML(){const areas=new Set(active().map(n=>n.folder.split('/')[0])),all=tagCounts(),isMeta=t=>metaTag(t)||areas.has(t),topic=all.filter(([t])=>!isMeta(t)),meta=all.filter(([t])=>isMeta(t));
 const row=([t,c])=>`<button data-tag="${esc(t)}" class="tag ${tag===t?'selected':''}"># ${esc(t)} <small>${c.toLocaleString()}</small></button>`;
 return `<details class="side-tags"${tag?' open':''}><summary>태그</summary><div>${topic.map(row).join('')}${meta.length?`<details class="meta-tags"${meta.some(([t])=>t===tag)?' open':''}><summary>연도·형식·출처·영역 태그 ${meta.length}개</summary><div>${meta.map(row).join('')}</div></details>`:''}</div></details>`;}
const tagCounts=()=>{const m=new Map();for(const n of active())for(const t of n.tags)m.set(t,(m.get(t)||0)+1);return [...m.entries()].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0],'ko'));};
const kindSummary=(idx,list)=>{if(!idx)return '';const m=new Map();for(const n of list){const k=idx.byId.get(n.id)?.kind;if(k)m.set(k,(m.get(k)||0)+1);}return m.size>1?KIND_ORDER.filter(k=>m.get(k)).map(k=>KINDS[k]+' '+m.get(k).toLocaleString()).join(' · '):'';};
// 지금 조건(노트북·태그·찾기 낱말·조건 줄)에 맞는 기록. 지식맵의 「지금 찾은 기록」이 쓴다.
function condNotes(){const idx=facets();return filterNotes(notes,{view:'all',folder,tag,q,fields:fields(),status,sort}).filter(n=>condEmpty(cond)||matchCond(idx.byId.get(n.id),cond));}
const countFor=s=>{const idx=facets();return filterNotes(notes,{view:'all',folder:s.folder||'',tag:s.tag||'',q:s.q||''}).filter(n=>condEmpty(s.cond)||matchCond(idx.byId.get(n.id),s.cond)).length;};
function savedHTML(){if(!savedQueries.length)return '';return `<div class="side-heading">저장한 찾기</div><div class="saved-list">${savedQueries.map(s=>`<div class="saved-row"><button class="nav-item" data-saved="${esc(s.id)}" title="${esc(s.name)}">${icon('search')}<span>${esc(s.name)}</span><small>${countFor(s).toLocaleString()}</small></button><button type="button" class="icon-button saved-x" data-action="saved-delete" data-id="${esc(s.id)}" aria-label="${esc(s.name)} 지우기">${icon('close')}</button></div>`).join('')}</div>`;}
function overviewView(){const idx=facets();return `<div class="overview-scroll">${overviewHTML(overviewStats(idx),idx,{demo})}</div>`;}
const facetLine=n=>{const idx=facets();return facetLineHTML(idx.byId.get(n.id),idx);};
// 같은 시기(앞뒤 1년)에 주제가 겹치는 기록: 함께 읽을 기록 아래에 붙인다.
function sameTimeHTML(n){const idx=facets(),row=idx.byId.get(n.id),list=sameTime(row,idx,5);if(!list.length)return '';const byId=new Map(active().map(x=>[x.id,x]));return `<section class="related same-time"><header><div><span class="eyebrow">같은 시기 · 같은 주제</span><h2>${row.year}년 앞뒤의 기록</h2></div><button type="button" class="quiet small" data-cond="${esc(JSON.stringify({y0:row.year-1,y1:row.year+1,themes:row.themes,themeMode:'or'}))}">모두 보기</button></header>${list.map(({r})=>{const o=byId.get(r.id);return o?`<button class="related-row" data-note="${esc(o.id)}">${icon('clock')}<span><strong>${esc(shortTitle(o))}</strong><small>${esc([r.year+'년',KINDS[r.kind],r.themes.filter(t=>row.themes.includes(t)).map(t=>idx.label[t]).join(', ')].join(' · '))}</small></span>${icon('link')}</button>`:'';}).join('')}</section>`;}
async function applyCond(c){await navigate(()=>{cond=c&&typeof c==='object'&&!Array.isArray(c)?c:{};view='all';folder='';tag='';q='';status='';scope='all';selected='';condOpen=false;if(layout==='cards'&&innerWidth>700)layout='list';});}
function condLabel(){const idx=facets(),c=cond,p=[];for(const k of c.kinds||[])p.push(KINDS[k]);if(c.y0||c.y1)p.push(c.y0&&c.y0===c.y1?c.y0+'년':(c.y0||'')+'~'+(c.y1||'')+'년');for(const t of c.themes||[])p.push(idx.label[t]||t);for(const t of c.tags||[])p.push('#'+t);for(const f of c.formats||[])p.push(f);for(const a of c.areas||[])p.push(a);if(q)p.push('“'+q+'”');if(folder)p.push(folder);if(tag)p.push('#'+tag);return p.join(' · ')||'모든 기록';}
// AI에게 건네기: 앱은 AI를 부르지 않는다. 사용자가 고른 기록을 글로 만들어 복사·저장하고, AI 답은 근거 기록과 이은 새 기록으로 남긴다.
function handoffDialog(){handoffList=listRows.slice();const n=handoffList.length;dialog('AI에게 건네기',`<p class="dialog-lead">지금 목록의 기록 ${n.toLocaleString()}개를 AI 대화창에 붙여 넣을 글로 만듭니다. 앱이 AI를 직접 부르지 않으니, 보낼 내용을 확인한 뒤 붙여 넣으세요.</p><label class="stack">AI에게 할 질문(선택)<textarea id="handoff-question" rows="3" placeholder="예: 이 기록들에서 다음 학기 수업으로 이어 볼 문제를 찾아 줘"></textarea></label><fieldset class="handoff-opts"><legend>넣을 내용</legend><label><input type="radio" name="handoff-include" value="meta" checked> 제목·날짜·노트북·주소</label><label><input type="radio" name="handoff-include" value="excerpt"> 본문 앞부분 300자까지</label><label><input type="radio" name="handoff-include" value="full"> 본문 전체</label></fieldset><label class="stack">최대 개수<select id="handoff-limit"><option value="50">50개</option><option value="100" selected>100개</option><option value="200">200개</option><option value="0">전체</option></select></label><p class="hint" id="handoff-size"></p><textarea id="handoff-out" rows="6" readonly hidden aria-label="복사할 글"></textarea><details class="handoff-back"><summary>AI가 준 답을 기록으로 남기기</summary><p class="hint">붙여 넣은 답은 건넨 기록들과 연결된 새 기록(태그 「AI 제안」)이 됩니다. 겪은 사실과 구분해 다시 읽고 고쳐 쓰세요.</p><textarea id="handoff-answer" rows="5" placeholder="AI의 답을 붙여 넣으세요"></textarea>${btn('handoff-note','답을 기록으로 남기기','check','quiet')}</details>`,btn('handoff-save','.md 파일로 저장','download')+btn('handoff-copy','복사','check','primary'));updateHandoffSize();}
function handoffOpts(){return {question:$('#handoff-question')?.value||'',include:$('[name=handoff-include]:checked')?.value||'meta',limit:Number($('#handoff-limit')?.value||0)};}
function handoffPicked(){const o=handoffOpts();return o.limit?handoffList.slice(0,o.limit):handoffList;}
function handoffBuild(){return handoffText(handoffList,facets(),handoffOpts());}
function updateHandoffSize(){const el=$('#handoff-size');if(!el)return;const t=handoffBuild();el.textContent=`기록 ${handoffPicked().length.toLocaleString()}개 · 약 ${t.length.toLocaleString()}자`+(t.length>150000?' · 너무 길면 AI가 다 읽지 못합니다. 개수를 줄이거나 제목만 넣으세요.':'');}
function randomDialog(){const pool=listRows.slice();for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}const idx=facets(),seen=new Set(),pick=[];for(const n of pool){const k=idx.byId.get(n.id)?.kind;if(pick.length<3&&!seen.has(k)){pick.push(n);seen.add(k);}}for(const n of pool)if(pick.length<3&&!pick.includes(n))pick.push(n);dialog('무작위 세 개',`<p class="dialog-lead">지금 목록 ${listRows.length.toLocaleString()}개에서 고른 기록입니다.</p>${pick.map(n=>{const r=idx.byId.get(n.id);return `<button class="related-row" data-note="${esc(n.id)}">${icon('all')}<span><strong>${esc(n.title||'제목 없음')}</strong><small>${esc([r?.year?r.year+'년':'',KINDS[r?.kind]||'',n.folder].filter(Boolean).join(' · '))}</small></span></button>`;}).join('')}`,btn('random3','다시 고르기','back')+btn('dialog-close','닫기','','primary'));}
const rulesText=rules=>rules.map(r=>r.label+': '+r.words.join(', ')).join('\n');
function parseRules(text){const out=[],seen=new Set();for(const line of String(text).split(/\r?\n/)){const m=/^\s*([^:：]+)[:：](.*)$/.exec(line);if(!m)continue;const label=m[1].trim(),words=m[2].split(/[,，]/).map(x=>x.trim()).filter(Boolean);if(!label||!words.length)continue;const id=THEME_PRESET.find(r=>r.label===label)?.id||'t-'+label;if(seen.has(id))continue;seen.add(id);out.push({id,label,words});}return out.slice(0,60);}
function themeRulesDialog(){dialog('주제 규칙',`<p class="dialog-lead">한 줄에 주제 하나를 「이름: 낱말, 낱말」로 적습니다. 제목·태그·노트북(직접 쓴 기록은 본문 앞부분까지)에 낱말이 하나라도 있으면 그 주제가 붙습니다. 태그는 바뀌지 않습니다.</p><textarea id="theme-rules-text" class="rules-text" rows="16" spellcheck="false">${esc(rulesText(themeRules||THEME_PRESET))}</textarea>`,btn('theme-rules-reset','기본값으로')+btn('theme-rules-save','저장하고 다시 계산','check','primary'));}
function prereqDialog(){dialog('준비 조건',`<p class="dialog-lead">기록 쓰기와 정리, 지식맵, 백업 파일은 브라우저만 있으면 됩니다. 드라이브에 있는 원본과 이어지는 기능은 PC에 구글 드라이브 데스크톱이 있어야 하고, 쓰는 폴더를 「오프라인으로 사용」으로 두어야 바로 열립니다. 「온라인에서만 사용 가능」으로 두면 파일을 열 때마다 내려받아 느리고, 인터넷이 끊기면 열리지 않습니다.</p><table class="prereq"><thead><tr><th>기능</th><th>필요한 것</th></tr></thead><tbody><tr><td>기록 쓰기·정리·지식맵·백업 파일</td><td>브라우저만</td></tr><tr><td>카드의 「원본 열기」·「드라이브 미리보기」, 바둑판 그림</td><td>그 파일을 볼 수 있는 구글 계정으로 브라우저 로그인</td></tr><tr><td>카드의 「탐색기」·「경로 복사」</td><td>구글 드라이브 데스크톱(파일 탐색기의 「Google Drive (G:)」). 「탐색기」는 탐색기 연결 도구도 설치</td></tr><tr><td>카드 파일 연결, PC 폴더 자동 백업</td><td>PC의 크롬·엣지. 파일과 폴더가 드라이브에 있으면 구글 드라이브 데스크톱과 「오프라인으로 사용」</td></tr><tr><td>변환기 Windows 앱·파이썬판</td><td>바꿀 폴더가 드라이브에 있으면 구글 드라이브 데스크톱과 「오프라인으로 사용」. 코랩판은 필요 없음</td></tr><tr><td>사이트 만들기(제작기)</td><td>PC의 크롬·엣지. 작업 폴더가 드라이브에 있으면 같은 준비</td></tr></tbody></table><ol class="prereq-steps"><li><a href="https://www.google.com/drive/download/" target="_blank" rel="noopener">구글 드라이브 데스크톱</a>을 설치하고 자료가 있는 구글 계정으로 로그인합니다.</li><li>파일 탐색기 왼쪽 「내 PC」 아래에 「Google Drive (G:)」가 생겼는지 봅니다.</li><li>G: 안의 「내 드라이브」나 쓰는 폴더를 마우스 오른쪽 단추로 눌러 「오프라인 액세스 › 오프라인으로 사용」을 고릅니다.</li><li>폴더 아이콘에 초록색 체크 표시가 붙을 때까지 기다립니다. 오프라인으로 둔 폴더 크기만큼 PC 저장 공간을 씁니다.</li></ol><p class="hint">「경로 복사」는 「${esc(driveRoot())}」로 시작하는 경로를 만듭니다. 드라이브 문자가 G가 아니거나 영어 화면(My Drive)이면 아래 단추로 바꿉니다.</p>`,btn('drive-root','구글 드라이브 위치 바꾸기','folder')+btn('dialog-close','닫기','','primary'));}
// 주소(#)에 지금 화면을 적어 두어 브라우저의 뒤로 가기·앞으로 가기가 앱 안에서도 통하게 한다.
function stateHash(){const p=new URLSearchParams();if(view!=='all')p.set('v',view);if(folder)p.set('f',folder);if(tag)p.set('t',tag);if(q)p.set('q',q);if(!condEmpty(cond))p.set('c',JSON.stringify(cond));if(selected&&view!=='overview'&&view!=='graph')p.set('n',selected);const s=p.toString();return s?'#'+s:'';}
function writeHash(){if(!hashReady||draft)return;const h=stateHash();if(h!==location.hash){try{const url=location.pathname+location.search+h;hashPush?history.pushState(null,'',url):history.replaceState(null,'',url);}catch{}}hashPush=false;}
function readHash(){const h=location.hash.slice(1);if(!h||h.startsWith('note='))return false;const p=new URLSearchParams(h);const v=p.get('v')||'all';if(!['all','overview','graph','inbox','review','favorites','trash'].includes(v))return false;view=v;folder=p.get('f')||'';tag=p.get('t')||'';q=p.get('q')||'';try{const c=p.has('c')?JSON.parse(p.get('c')):{};cond=c&&typeof c==='object'&&!Array.isArray(c)?c:{};}catch{cond={};}const n=p.get('n');if(n&&notes.some(x=>x.id===n))selected=n;else if(view==='overview')selected='';return true;}
window.addEventListener('popstate',()=>run(async()=>{if(draft&&!(await saveDraft(false)))return;draft=null;dirty=false;if(!readHash()){view='all';folder='';tag='';q='';cond={};}hashPush=false;render();}));
document.addEventListener('toggle',e=>{if(e.target.classList?.contains('cond-panel'))condOpen=e.target.open;if(e.target.classList?.contains('properties')&&e.target.open)fillTagSuggest();},true);
