async function vaultFiles(){if(draft&&!(await saveDraft(false)))throw Error('저장 후 다시 시도해 주세요.');const files={};for(const n of active()){const dir=n.folder.split('/').map(safeName).join('/');if(n.database)files[dir+'/'+safeName(n.title)+'--'+n.id+'.database.json']=strToU8(n.database);files[dir+'/'+safeName(n.title)+'--'+n.id+'.md']=strToU8(markdownFile(n,notes,assets).replaceAll('(attachments/','('+'../'.repeat(dir.split('/').length)+'attachments/'));}const used=new Set(active().flatMap(n=>n.attachments));for(const a of assets.filter(a=>used.has(a.id)))files['attachments/'+a.id+'-'+safeName(a.name)]=new Uint8Array(await a.blob.arrayBuffer());files['서재 안내.md']=strToU8('# PKOS에서 내보낸 기록\n\n각 노트북의 Markdown과 attachments 폴더를 함께 보관하세요.\n휴지통 기록은 포함하지 않습니다.\n');return files;}
async function restoreFile(file){if(!file)return;if(file.size>80*1024*1024)throw Error('이 버전은 80MB까지의 백업을 가져올 수 있습니다. 큰 백업의 원본 파일은 삭제하지 마세요.');let data;try{data=validateBackup(JSON.parse(await file.text()));}catch(e){throw Error((file.name?file.name+': ':'')+(e instanceof SyntaxError?'PKOS 백업·카드 파일이 아니거나 내용이 손상되었습니다.':e.message));}const updatable=data.notes.some(n=>n.updatable===true),stubs=data.notes.filter(n=>n.deleted&&n.updatable===true).length,num=v=>v.toLocaleString();if(!await ask('백업 가져오기',`${num(data.notes.length-stubs)}개 기록을 현재 서재에 더합니다.${stubs?` 정리 표시 ${num(stubs)}개는 이미 가져온 같은 카드를 휴지통으로 옮길 때만 씁니다.`:''} 같은 ID의 내용이 다르면 사본으로 보존합니다.${updatable?' 이미 가져온 자료 카드 가운데 앱에서 고치지 않은 것은 새 내용으로 바꾸고, 고친 카드는 그대로 둡니다.':''}`,{value:null,confirm:'가져오기'}))return;const result=await db.mergeBackup(data);await load();selected=active()[0]?.id||'';draft=null;render();toast(`${num(result.added)}개 기록을 가져왔습니다.${result.updated?` 갱신 ${num(result.updated)}개.`:''}${result.retired?` 정리 ${num(result.retired)}개(휴지통).`:''}${result.kept?` 고친 카드 ${num(result.kept)}개는 그대로 둠.`:''} 충돌 사본 ${num(result.copies)}개.`);}
async function run(fn){try{if(!await flushDatabases())return;await fn();}catch(e){console.error(e);toast(e.name==='AbortError'?'취소했습니다.':e.message||'작업을 완료하지 못했습니다.');}}
