function watchExplorerLink(){let left=false;const away=()=>{left=true;};window.addEventListener('blur',away,{once:true});document.addEventListener('visibilitychange',away,{once:true});setTimeout(()=>{window.removeEventListener('blur',away);document.removeEventListener('visibilitychange',away);if(!left)toast('탐색기가 열리지 않으면 이 PC에 탐색기 연결 도구가 없는 것입니다. 「경로 복사」를 눌러 탐색기 주소창(Ctrl+L)에 붙여 넣으세요.');},2000);}
document.addEventListener('click',e=>{if(e.target.closest('a[href^="pkos-open:"]'))watchExplorerLink();
 const openCond=document.querySelector('#cond-bar .cond-panel[open]');if(openCond&&!e.target.closest('#cond-bar')){openCond.open=false;condOpen=false;}
 const cd=e.target.closest('[data-cond]');if(cd){e.preventDefault();let c={};try{c=JSON.parse(cd.dataset.cond);}catch{}if(cd.closest('#dialog'))$('#dialog').close();run(()=>applyCond(c));return;}
 const ct=e.target.closest('[data-cond-toggle]');if(ct){const [k,val]=ct.dataset.condToggle.split('\u0001');const list=cond[k]||[];cond={...cond,[k]:list.includes(val)?list.filter(x=>x!==val):[...list,val]};condOpen=true;hashPush=true;renderList();writeHash();return;}
 const cr=e.target.closest('[data-cond-remove]');if(cr){let r={};try{r=JSON.parse(cr.dataset.condRemove);}catch{}const c={...cond};for(const [k,val] of Object.entries(r)){if(k==='years'){delete c.y0;delete c.y1;}else if(k==='special')delete c.special;else c[k]=(c[k]||[]).filter(x=>x!==val);}cond=c;hashPush=true;renderList();writeHash();return;}
 const cs=e.target.closest('[data-cond-set]');if(cs){let r={};try{r=JSON.parse(cs.dataset.condSet);}catch{}cond={...cond,...r};hashPush=true;renderList();writeHash();return;}
 const cm=e.target.closest('[data-cond-mode]');if(cm){const [k,val]=cm.dataset.condMode.split(':');cond={...cond,[k]:val};renderList();writeHash();return;}
 const sv=e.target.closest('[data-saved]');if(sv){const s=savedQueries.find(x=>x.id===sv.dataset.saved);if(s)run(()=>navigate(()=>{view='all';cond=structuredClone(s.cond||{});q=s.q||'';folder=s.folder||'';tag=s.tag||'';status='';selected='';}));return;}
 const at=e.target.closest('[data-add-tag]');if(at){const i=$('#edit-tags');if(i){const tags=tagsOf(i.value);if(!tags.includes(at.dataset.addTag))tags.push(at.dataset.addTag);i.value=tags.join(', ');i.dispatchEvent(new Event('input',{bubbles:true}));fillTagSuggest();}return;}const pk=e.target.closest('[data-peek]');if(pk){showPeek(pk.dataset.peek);return;}if(view==='graph'&&mapPeek&&e.target.closest('#graph-area .map2d, #graph-area .map3d')&&!e.target.closest('[data-note],[data-action]'))closePeek();const n=e.target.closest('[data-note]');if(n){e.preventDefault();if(n.closest('#dialog'))$('#dialog').close();if(view==='graph'&&n.closest('#graph-area')){showPeek(n.dataset.note);return;}run(()=>openNote(n.dataset.note));return;}const v=e.target.closest('[data-view]');if(v){run(()=>navigate(()=>{view=v.dataset.view;folder='';tag='';q='';cond={};mapScope='all';condOpen=false;selected=innerWidth<=700?'':firstRecord({view});}));return;}const ft=e.target.closest('[data-folder-toggle]');if(ft){toggleFolder(ft.dataset.folderToggle);return;}const f=e.target.closest('[data-folder]');if(f){run(()=>navigate(()=>{folder=f.dataset.folder;tag='';view='all';selected=innerWidth<=700?'':hubFor(folder)?.id||firstRecord({folder});}));return;}const t=e.target.closest('[data-tag]');if(t){run(()=>navigate(()=>{tag=t.dataset.tag;folder='';view='all';selected=innerWidth<=700?'':firstRecord({tag});}));return;}const el=e.target.closest('[data-action]');if(el)run(()=>handle(el.dataset.action,el));});
document.addEventListener('input',e=>{if(e.target.id==='handoff-question')updateHandoffSize();if(e.target.id==='search'){q=e.target.value;renderList();if(innerWidth>700&&q.trim()&&selected&&!draft&&!listRows.some(n=>n.id===selected)){selected='';renderSummary(rowIdx);writeHash();}}if(e.target.id==='edit-tags')fillTagSuggest();if(e.target.id==='link-search'&&$('#dialog .link-choices'))$('#dialog .link-choices').innerHTML=linkPickerRows(e.target.value);});
document.addEventListener('error',e=>{if(e.target instanceof HTMLImageElement&&e.target.classList.contains('thumb'))e.target.classList.add('broken');},true);
document.addEventListener('change',e=>{if(e.target.dataset?.linkId){e.target.checked?pickerSel.add(e.target.dataset.linkId):pickerSel.delete(e.target.dataset.linkId);return;}if(e.target.dataset?.condYear){const k=e.target.dataset.condYear,val=Number(e.target.value)||0;const c={...cond};if(val)c[k]=val;else delete c[k];if(c.y0&&c.y1&&c.y0>c.y1){const t=c.y0;c.y0=c.y1;c.y1=t;}cond=c;hashPush=true;renderList();writeHash();return;}if(e.target.dataset?.mapScope!==undefined){mapScope=e.target.value;drawGraph();return;}if(e.target.closest?.('#dialog')&&(e.target.name==='handoff-include'||e.target.id==='handoff-limit')){updateHandoffSize();return;}if(e.target.dataset?.mapOption){const k=e.target.dataset.mapOption;mapOptions={...mapOptions,[k]:k==='count'?Number(e.target.value):e.target.value};try{localStorage.setItem('pkos-map-options',JSON.stringify(mapOptions));}catch{}drawGraph();return;}if(e.target.id==='search-scope'){scope=e.target.value;renderList();}if(e.target.id==='status-filter'){status=e.target.value;renderList();}if(e.target.id==='sort'){sort=e.target.value;renderList();}if(e.target.dataset.graphCriterion){graphFilters=$$('[data-graph-criterion]:checked').map(i=>i.dataset.graphCriterion);saveCriteria();$('#criteria-count').textContent=graphFilters.length;drawGraph();}if(e.target.dataset.graphWeight){graphWeights[e.target.dataset.graphWeight]=Number(e.target.value);saveCriteria();e.target.nextElementSibling.textContent=e.target.value+'배';drawGraph();}if(e.target.id==='font-size'){localStorage.setItem('pkem-font',e.target.value);document.documentElement.style.setProperty('--reading-size',e.target.value+'px');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!document.querySelector('dialog[open]')){if(editorToolsOpen&&$('#editor-extra-tools')){setEditorTools(false);$('[data-action="editor-tools"]')?.focus();}else if(writingFocus)toggleWritingFocus();}closeNavigation();}if((e.ctrlKey||e.metaKey)&&!e.altKey&&e.key.toLowerCase()==='e'&&view!=='overview'&&view!=='graph'&&$('.document')?.getClientRects().length&&(draft||(current()&&!current().deleted))&&!document.querySelector('dialog[open]')){e.preventDefault();run(()=>handle(draft?'preview':'edit'));}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();run(()=>handle('search'));}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'&&draft){e.preventDefault();run(()=>saveDraft(false));}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='b'&&e.target.id==='edit-body'){e.preventDefault();run(()=>handle('bold'));}if((e.key==='Enter'||e.key===' ')&&e.target.matches('g[data-action]')){e.preventDefault();run(()=>handle(e.target.dataset.action,e.target));}if(e.key==='Enter'&&e.target.matches('g[data-note]')){if(view==='graph')showPeek(e.target.dataset.note);else run(()=>openNote(e.target.dataset.note));}});
