document.documentElement.style.setProperty('--reading-size',(localStorage.getItem('pkem-font')||17)+'px');
let resizeTimer;
window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(view==='graph'&&$('#graph-area'))drawGraph();},100);});
const documentPagesAPI={
 toast,
 async savePage(job,page){
  const note=await db.get('notes',job.noteId);if(!note||note.deleted||!note.attachments.includes(job.asset.id))throw Error('원본이 있는 기록을 찾지 못했습니다.');
  if(pagesOf(note).some(p=>p.sourceAssetId===job.asset.id&&p.number===page.number))return;
  if(pagesOf(note).length>=2000)throw Error('한 기록에는 페이지 이미지 2,000개까지 보관할 수 있습니다.');
  if(!(page.blob instanceof Blob)||page.blob.type!=='image/png'||!page.blob.size||page.blob.size>20*1024*1024||!Number.isInteger(page.number)||page.number<1)throw Error('페이지 이미지 형식을 확인하지 못했습니다.');
  const image={id:uid(),name:job.asset.name.replace(/\.[^.]+$/,'')+'-'+String(page.number).padStart(3,'0')+'.png',type:'image/png',blob:page.blob};
  const item={id:uid(),sourceAssetId:job.asset.id,assetId:image.id,number:page.number,comment:'',deleted:false};
  const saved=await db.saveCaptured({...note,attachments:[...note.attachments,image.id],documentPages:[...pagesOf(note),item]},note.revision,image);
  notes=notes.map(n=>n.id===saved.id?saved:n);assets.push(image);
  if(draft?.id===saved.id){draft={...draft,revision:saved.revision,updated:saved.updated,attachments:saved.attachments,documentPages:saved.documentPages};}
  channel?.postMessage({id:saved.id});
 },
 async finish(){await folderMirror?.sync();render();}
};
// Dropping files anywhere in the workspace attaches to the current draft, or
// creates a record when the user is reading. Browser navigation is prevented.
document.addEventListener('dragover',event=>{
 if(!Array.from(event.dataTransfer?.types||[]).includes('Files'))return;
 event.preventDefault();event.dataTransfer.dropEffect=document.querySelector('dialog[open]')?'none':'copy';
});
document.addEventListener('drop',event=>{
 const files=Array.from(event.dataTransfer?.files||[]);if(!files.length)return;
 event.preventDefault();if(document.querySelector('dialog[open]')){toast('열려 있는 창을 닫은 뒤 파일을 놓아 주세요.');return;}
 const attach=!!draft,ownerId=draft?.id;void run(()=>importFiles(files,attach,ownerId));
});
const documentToolsAPI={
 toast,open:id=>run(()=>openNote(id)),
 async save(job,result){
  const source=await db.get('notes',job.noteId);if(!source||source.deleted)throw Error('원본 기록이 삭제되어 추출 결과를 저장하지 않았습니다.');
  const existing=(await db.all('notes')).find(n=>!n.deleted&&n.conversion?.assetId===job.asset.id&&n.conversion.sha===result.originalSha);if(existing)return existing.id;
  let size=0;const extracted=[];
  for(const [i,image] of result.extractedImages.entries()){
   if(!/^data:image\/png;base64,[A-Za-z0-9+/=]+$/.test(image.dataUrl))throw Error('추출 이미지 형식을 확인하지 못했습니다.');
   const bytes=Uint8Array.from(atob(image.dataUrl.split(',')[1]),c=>c.charCodeAt(0));size+=bytes.length;if(size>20*1024*1024)throw Error('추출 이미지가 20MB를 넘었습니다.');
   extracted.push({id:uid(),name:'추출-'+(i+1)+'-'+String(image.name||'image.png').replace(/[\\/:*?"<>|]/g,'_'),type:'image/png',blob:new Blob([bytes],{type:'image/png'})});
  }
  const warnings=Array.isArray(result.warnings)?result.warnings.map(String):[];
  const note=makeNote({title:job.asset.name.replace(/\.[^.]+$/,'')+' · 추출',folder:source.folder,tags:[...new Set([...source.tags,'문서추출'])],links:[source.id],attachments:[job.asset.id,...extracted.map(a=>a.id)],body:'# '+job.asset.name+' — 추출한 본문\n\n'+result.body+(warnings.length?'\n\n---\n\n### 추출 안내\n'+warnings.map(w=>'- '+w).join('\n'):''),conversion:{assetId:job.asset.id,sha:result.originalSha,kind:result.kind,at:new Date().toISOString(),warnings}});
  const saved=await db.saveCaptured(note,0,[job.asset,...extracted],null);
  await load();if(!draft){selected=saved.id;view='all';folder='';tag='';q='';status='';render();}else renderList();channel?.postMessage('changed');return saved.id;
 }
};
const processingAPI={saveResult:async note=>{const saved=await db.save(note,0);await load();if(!draft){selected=saved.id;view='all';render();}channel?.postMessage({id:saved.id});toast('처리 결과를 원본과 연결하여 저장했습니다.');}};
const editorToolsAPI={
 note:()=>draft?{id:draft.id,title:draft.title}:null,
 attach:accept=>chooseFiles('attach',accept),
 toast,download,
 recoveryWrite:record=>db.put('meta',record),
 recoveryList:async()=>(await db.all('meta')).filter(r=>r.id.startsWith('capture-recovery-')).sort((a,b)=>b.updated.localeCompare(a.updated)),
 recoveryDelete:id=>db.deleteMeta(id),
 commit:async({ownerId,file,text,recoveryId})=>{
  if(!draft||draft.id!==ownerId)throw Error('저장할 기록이 바뀌었습니다. 원본을 내려받은 뒤 다시 첨부해 주세요.');
  if(file&&file.size>20*1024*1024)throw Error('첨부 한 개는 20MB까지입니다. 원본을 내려받아 별도로 보관해 주세요.');
  if(!(await saveDraft(false)))throw Error('기존 글을 저장하지 못했습니다. 글과 첨부를 확인해 주세요.');
  const snapshot=structuredClone(draft),asset=file?{id:uid(),name:file.name,type:file.type,blob:file}:null;
  if(asset)snapshot.attachments.push(asset.id);
  if(text)snapshot.body+=(snapshot.body?'\n\n':'')+'## 받아쓴 글\n\n'+text;
  const saved=await db.saveCaptured(snapshot,snapshot.revision,asset,recoveryId);
  draft=saved;dirty=false;saveError='';const idx=notes.findIndex(n=>n.id===saved.id);if(idx<0)notes.unshift(saved);else notes[idx]=saved;if(asset)assets.push(asset);render();setSaveState('저장됨');channel?.postMessage({id:saved.id});if(asset?.type.startsWith('audio/')&&localStorage.getItem('pkos-auto-transcribe')==='1')showProcessing('transcribe',asset,saved,processingAPI,{automatic:true});
 }
};
init();
document.addEventListener('scroll',e=>{const l=e.target;if(l?.id==='note-list'&&l.scrollTop+l.clientHeight>l.scrollHeight-500)appendRows();},true);
document.addEventListener('toggle',e=>{const d=e.target;if(!d.classList?.contains('map-records')||!d.open||d.dataset.filled)return;d.dataset.filled='1';const byId=new Map(active().map(n=>[n.id,n]));d.querySelector('.map-record-list').innerHTML=mapListed.map(id=>byId.get(id)).filter(Boolean).map(n=>`<button data-note="${esc(n.id)}">${esc(shortTitle(n))}</button>`).join('');},true);

async function addDatabaseFiles(id,files){if(files.length>50||files.some(f=>f.size>20*1024*1024))throw Error('파일은 한 번에 50개, 하나에 20MB까지 첨부할 수 있습니다.');const note=await db.get('notes',id);if(!note||note.deleted)throw Error('데이터베이스를 찾을 수 없습니다.');const rows=files.map(f=>({id:uid(),name:f.name,type:f.type||'application/octet-stream',blob:f}));const saved=await db.saveCaptured({...note,attachments:[...note.attachments,...rows.map(a=>a.id)]},note.revision,rows);notes=notes.map(n=>n.id===id?saved:n);assets=[...assets,...rows];channel?.postMessage({id});return rows;}
